<?php

# @autogenerated
declare(strict_types=1);

use Civi\Lughauth\Features\Access\ApiKeyClient\Domain\ValueObject\Accessor\ApiKeyClientScopesAccessor;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the ApiKeyClientScopesAccessor trait.
 *
 * Covers null default, string/VO assignment via withScopes,
 * getScopes/scopes accessors, and isScopesChanged with/without original.
 */
class ApiKeyClientScopesAccessorUnitTest extends TestCase
{
    /**
     * Asserts that withScopes creates a new instance with the Scopes set
     * from a string value, and getScopes returns the primitive string.
     */
    public function testWithScopesFromString(): void
    {
        // Arrange
        $holder = new ImplWithApiKeyClientScopesAccessorUnitTest();

        // Act
        $result = $holder->withScopes('one');

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals('one', $result->getScopes());
    }
    /**
     * Asserts that withscopes has access to the value object
     * from a string value, and getScopes returns the primitive string.
     */
    public function testWithScopesFromValueObject(): void
    {
        // Arrange
        $holder = new ImplWithApiKeyClientScopesAccessorUnitTest();

        // Act
        $result = $holder->withScopes('one');

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals('one', $result->scopes()->value());
    }
    public function testChangedScopes(): void
    {
        // Arrange
        $holder = new ImplWithApiKeyClientScopesAccessorUnitTest();
        $original = $holder->withScopes('one');
        $same = $holder->withScopes('one');
        $modified = $holder->withScopes('other');

        // Act
        $unchanged = $holder->isScopesChanged();
        $withSame = $original->isScopesChanged($same);
        $withDiferent = $original->isScopesChanged($modified);

        // Assert
        $this->assertFalse($unchanged);
        $this->assertFalse($withSame);
        $this->assertTrue($withDiferent);
    }
}
class ImplWithApiKeyClientScopesAccessorUnitTest
{
    use ApiKeyClientScopesAccessor;
}
